contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool ownerCall) public payable {
        require(ownerCall);

        uint256 balanceBefore = address(c).balance;

        c.sudicideAnyone(); if (__ESBMC_reverted()) return;

        assert(address(c).balance == 0);
    }

    receive() external payable {}
}

