pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool ownerCall) internal {
        vm.assume(ownerCall);
        uint256 balanceBefore = address(c).balance;
        try c.sudicideAnyone() {} catch { return; }
        assertTrue(address(c).balance == 0);
    }

    function testFuzz_run(bool ownerCall) public {
        _run(ownerCall);
    }

    receive() external payable {}
}
